    89  void vcardstructured_ref(vcardstructuredtype *st)
    90  {
    91      icalerror_check_arg_rv((st != NULL), "st");
    92
    93      st->refcount++;
    94  }
    95
    96  void vcardstructured_unref(vcardstructuredtype *st)
    97  {
    98      icalerror_check_arg_rv((st != NULL), "st");
    99      icalerror_check_arg_rv((st->refcount > 0), "st->refcount > 0");
   100
   101      st->refcount--;
   102
   103      if (st->refcount != 0) {
   104          return;
   105      }
   106
   107      vcardstructured_free(st);
   108  }
