   135  void vcardstructured_set_num_fields(vcardstructuredtype *st,
   136                                      size_t num_fields)
   137  {
   138      icalerror_check_arg_rv((st != NULL), "st");
   139
   140      for (size_t i = num_fields; i < st->num_fields; i++) {
   141          vcardstrarray_free(st->field[i]);
   142      }
   143
   144      st->num_fields = num_fields;
   145  }
