   147  vcardstrarray *vcardstructured_field_at(const vcardstructuredtype *st,
   148                                          size_t position)
   149  {
   150      icalerror_check_arg_rz((st != NULL), "st");
   151      icalerror_check_arg_rz((st->num_fields > position), "position");
   152
   153      return st->field[position];
   154  }
   155
   156  void vcardstructured_set_field_at(vcardstructuredtype *st,
   157                                    size_t position,
   158                                    vcardstrarray *field)
   159  {
   160      icalerror_check_arg_rv((st != NULL), "st");
   161
   162      if (position >= st->num_fields) {
   163          vcardstructured_set_num_fields(st, position + 1);
   164      }
   165
   166      vcardstrarray_free(st->field[position]);
   167      st->field[position] = field;
   168  }
