   212      if (param->value_kind == VCARD_INTEGER_VALUE) {
   213          param->data = atoi(val);
   214
   215      } else if (param->value_kind == VCARD_DATEANDORTIME_VALUE) {
   216          ((struct vcardparameter_impl *)param)->date = vcardtime_from_string(val, 0);
   217
   218      } else if (param->value_kind == VCARD_TEXT_VALUE) {
   219          ((struct vcardparameter_impl *)param)->string = icalmemory_strdup(val);
   220
   221      } else if (param->value_kind == VCARD_STRUCTURED_VALUE) {
